// useFleetDirectorBridge (#architect-creates-a-director-with-discovery) — apply a
// `bsc fleet director new` request and ACK it.
//
// THE ROUND TRIP
//   bsc fleet director new <key> → request file → Rust watcher (resolves the project, refuses a live
//   director, seeds prompts/director-kickoff.md) → `bsc://fleet-director` → HERE → fleetStartProject
//   → `fleet_director_ack`
//
// A thin adapter: the DECISION lives in `fleetDirectorBridge.ts`, unit-testable without Tauri.
//
// THIS IS NOT AN INJECTION PATH. The director's context is BAKED INTO THE LAUNCH as claude's
// initial-message argument — the same delivery the kickoff doc always used. Nothing is typed into a
// running session, and `injectCallers.test.ts` stays green on its empty set.
//
// WHY THE DOC IS READ HERE RATHER THAN AT LAUNCH (#the-director-launches-with-no-kickoff-prompt)
// `fleetStartProject` seeds the kickoff as a doc PATH, which TerminalView resolves once inside its
// launch effect. That is the route whose silent-loss failure is documented on the `startupPrompt`
// prop — the one that left every debug session "a bare `claude` with nothing to do" until debug and
// studio sessions were migrated off it. The director never was.
//
// So this resolves the doc to text FIRST and hands it to `applyDirectorNew`, which seeds it before any
// pane exists. `read_document` failing is not fatal: the launch proceeds and the doc route stays as
// the fallback, because a director delivered the old way beats no director at all.
import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { log } from "@/shared/lib/core/log";
import { scriptDocRelpath } from "@/features/planner/session/planningSession";
import { sanitizeProjectKey } from "@/shared/lib/core/projectPaths";
import { applyDirectorNew, type DirectorRequest, type DirectorAck } from "@/app/fleetDirectorBridge";

/** The hub-relative kickoff every director launch reads, resolved in Rust before the emit. */
const KICKOFF_RELPATH = "prompts/director-kickoff.md";

/** Listen for `bsc://fleet-director` and launch it. Mounted once by the shell. */
export function useFleetDirectorBridge(): void {
  useEffect(() => {
    let disposed = false;
    const un = listen<DirectorRequest>("bsc://fleet-director", (e) => {
      const req = e.payload;
      void (async () => {
        // Resolve the kickoff BEFORE the launch. A failure is logged and carried as `undefined` — the
        // launch still happens and falls back to the doc route rather than refusing to create the
        // director the architect asked for.
        let kickoffText: string | undefined;
        try {
          const relpath = scriptDocRelpath(sanitizeProjectKey(req.projectKey ?? ""), KICKOFF_RELPATH);
          const text = await invoke<string>("read_document", { relpath });
          kickoffText = typeof text === "string" && text.trim() ? text : undefined;
          if (!kickoffText) log.warn(`fleet director ${req.id}: ${relpath} is empty — falling back to the doc route`);
        } catch (err) {
          log.warn(`fleet director ${req.id}: kickoff read failed (${String(err)}) — falling back to the doc route`);
        }

        let ack: DirectorAck;
        try {
          ack = applyDirectorNew(
            req,
            {
              // Read off a LIVE getState, not a captured snapshot — zustand hands out a new object per
              // update, so a stale closure could launch against an older tab list.
              fleetStartProject: (name, fleet, key, paths) =>
                useAppStore.getState().fleetStartProject(name, fleet, key, paths),
              seedStartupPromptText: (paneId, text) =>
                useAppStore.setState((s) => ({
                  paneStartupPromptText: { ...s.paneStartupPromptText, [paneId]: text },
                })),
            },
            kickoffText,
          );
        } catch (err) {
          ack = {
            id: req.id,
            error: `fleet director threw: ${err instanceof Error ? err.message : String(err)}`,
            created: false,
          };
          log.error(`fleet director ${req.id} threw: ${String(err)}`);
        }
        void invoke("fleet_director_ack", { ack: { ...ack, id: req.id } }).catch((e2) => {
          // Nothing left to do — the caller will time out. Log it so the cause isn't a mystery.
          log.error(`fleet_director_ack failed for ${req.id}: ${String(e2)}`);
        });
      })();
    });
    return () => {
      disposed = true;
      void un.then((f) => {
        if (disposed) f();
      });
    };
  }, []);
}
